mapper.select:
/* CastDepMapper.retrieveUserDepList */
SELECT
    A.DPTGT_NO,
    A.OPER_YN AS OPR_YN,
    NVL(A.SCSH_CNTOM, 0) AS SCSH_CNTOM,
    NVL(A.GNRL_SRCH_CNTOM, 0) AS GNRL_SRCH_CNTOM,
    NVL(A.SMART_PASS_SRCH_CNTOM, 0) AS SMART_PASS_SRCH_CNTOM
FROM PMOWN.TN_PM_SMLT_USER_DPTGT A
WHERE 1 = 1
AND A.OWNER_USER_ID = #{loginUserId}
AND A.EXCN_YMD = #{ymd}
AND A.TMNL_ID = #{fcltTmnlId}
ORDER BY A.DPTGT_NO

/* CastDepMapper.retrieveUserDepOperHrList */
SELECT
    A.DPTGT_NO,
    NVL(A.OPER_BGNG_HOUR, 0) AS OPER_BGNG_HOUR,
    NVL(A.OPER_END_HOUR, 0) AS OPER_END_HOUR
FROM PMOWN.TN_PM_SMLT_USER_DPTGT_OPER_HR A
WHERE 1 = 1
AND A.OWNER_USER_ID = #{loginUserId}
AND A.EXCN_YMD = #{ymd}
AND A.TMNL_ID = #{fcltTmnlId}
ORDER BY A.DPTGT_NO, A.OPER_HR_SN

mapper.delete:
/* CastDepMapper.deleteUserDepList */
DELETE FROM PMOWN.TN_PM_SMLT_USER_DPTGT
WHERE 1 = 1
AND OWNER_USER_ID = #{loginUserId}
AND EXCN_YMD = #{ymd}
AND TMNL_ID = #{fcltTmnlId}

/* CastDepMapper.deleteUserDepOperHrList */
DELETE FROM PMOWN.TN_PM_SMLT_USER_DPTGT_OPER_HR
WHERE 1 = 1
AND OWNER_USER_ID = #{loginUserId}
AND EXCN_YMD = #{ymd}
AND TMNL_ID = #{fcltTmnlId}

mapper.insert:
/* CastDepMapper.insertUserDepList */ INSERT ALL
INTO PMOWN.TN_PM_SMLT_USER_DPTGT ( OWNER_USER_ID, EXCN_YMD, TMNL_ID, DPTGT_NO, OPER_YN, SCSH_CNTOM, GNRL_SRCH_CNTOM, SMART_PASS_SRCH_CNTOM, FRST_RGTR_ID, FRST_RGTR_IP_ADDR, FRST_REG_DT ) VALUES ( #{loginUserId}, #{ymd}, #{fcltTmnlId}, #{dep.dptgtNo}, #{dep.oprYn}, #{dep.scshCntom}, #{dep.gnrlSrchCntom}, #{dep.smartPassSrchCntom}, #{loginUserId}, #{loginIpAddr}, CURRENT_TIMESTAMP )
SELECT 1 FROM DUAL

/* CastDepMapper.insertUserDepOperHrList */ INSERT ALL
INTO PMOWN.TN_PM_SMLT_USER_DPTGT_OPER_HR ( OWNER_USER_ID, EXCN_YMD, TMNL_ID, DPTGT_NO, OPER_HR_SN, OPER_BGNG_HOUR, OPER_END_HOUR, FRST_RGTR_ID, FRST_RGTR_IP_ADDR, FRST_REG_DT ) VALUES ( #{loginUserId}, #{ymd}, #{fcltTmnlId}, #{dep.dptgtNo}, #{oprTimeIdx} + 1, #{oprTime.operBgngHour}, #{oprTime.operEndHour}, #{loginUserId}, #{loginIpAddr}, CURRENT_TIMESTAMP )
SELECT 1 FROM DUAL
